pragma solidity 0.8.36;
type Wad is uint256; function add(Wad left, Wad right) pure returns (Wad) { return Wad.wrap(Wad.unwrap(left) + Wad.unwrap(right)); } using {add as +} for Wad global; contract C { function sum(Wad left, Wad right) external pure returns (Wad) { return left + right; } }
